import type { DiscriminationTable, Flashcard, MCQItem } from '@/lib/types'

// v1 hand-authored study content, grounded in the corpus files referenced by
// each topic in topics.ts. Not exhaustive (Section 3: don't invent — this is
// a representative slice), structured so more items are easy to append.

export const FLASHCARDS: Flashcard[] = [
  { id: 'fc-agent-def', topicId: 'agents-what-is-an-agent', front: 'What makes something an "AI agent" rather than just a chat model?', back: 'It operates independently: it understands context, makes decisions, and takes actions toward a goal, usually by calling tools — not just generating text in response to a prompt.' },
  { id: 'fc-agent-loc', topicId: 'agents-what-is-an-agent', front: 'What does Microsoft Foundry Agent Service manage for you that you\'d otherwise build yourself?', back: 'Compute/storage, the tool-calling lifecycle, conversation state (via the Responses API), and security — so you can build an agent in under ~50 lines of code instead of hand-rolling orchestration.' },
  { id: 'fc-agent-types', topicId: 'agents-types', front: 'Declarative agent vs. hosted agent — what\'s the real difference?', back: 'Declarative = defined by configuration (instructions, model, tools), no custom code, runs on the platform. Hosted = a containerized agent you write and deploy yourself; the platform manages infra but you own the logic.' },
  { id: 'fc-agent-workflow-type', topicId: 'agents-types', front: 'What is a "workflow agent" (as opposed to a prompt-based agent)?', back: 'A declarative agent defined in YAML that orchestrates multiple agents together, rather than being a single model+instructions+tools configuration.' },
  { id: 'fc-executors-edges', topicId: 'agents-workflows', front: 'In the Microsoft Agent Framework, what are executors and edges?', back: 'Executors are the workers (an agent or custom logic) that take input and produce output. Edges define how messages flow between executors — direct, conditional, switch-case, fan-out, or fan-in.' },
  { id: 'fc-orchestration-why', topicId: 'agents-workflows', front: 'Why use multi-agent orchestration instead of one agent with a long instruction set?', back: 'A single agent is constrained to one model/prompt. Multiple specialized agents let you assign distinct skills, combine outputs for better accuracy, and dynamically route work — solving problems too complex for one agent.' },
  { id: 'fc-orch-concurrent', topicId: 'agents-orchestration-patterns', front: 'Concurrent orchestration — what is it for?', back: 'Broadcast the same task to multiple agents at once, collect results independently. Use for parallel analysis, independent subtasks, ensemble decisions.' },
  { id: 'fc-orch-sequential', topicId: 'agents-orchestration-patterns', front: 'Sequential orchestration — what is it for?', back: 'Pass output from one agent to the next in a fixed order. Use for pipelines and progressive refinement.' },
  { id: 'fc-orch-handoff', topicId: 'agents-orchestration-patterns', front: 'Handoff orchestration — what is it for?', back: 'Dynamically transfer control between agents based on context/rules, one agent working at a time. Use for escalation, fallback, expert routing.' },
  { id: 'fc-orch-groupchat', topicId: 'agents-orchestration-patterns', front: 'Group chat orchestration — what is it for?', back: 'A shared conversation among multiple agents (optionally a human), with a chat manager choosing who speaks next. Use for brainstorming and consensus-building.' },
  { id: 'fc-orch-magentic', topicId: 'agents-orchestration-patterns', front: 'Magentic orchestration — what is it for?', back: 'A manager-driven approach that plans, delegates, and adapts across specialized agents. Use for complex, open-ended problems where the solution path isn\'t known upfront.' },
  { id: 'fc-tools-default', topicId: 'agents-tools-overview', front: 'By default, who decides which tool an agent uses and when?', back: 'The model does, based on the prompt — but you can configure tool selection rules and steer choice via the Instructions (system prompt) parameter.' },
  { id: 'fc-tool-code-interpreter', topicId: 'agents-builtin-tools', front: 'What does the code_interpreter tool give an agent?', back: 'A Python environment where the model can generate and run code.' },
  { id: 'fc-tool-web-search', topicId: 'agents-builtin-tools', front: 'What does the web_search tool give an agent that its training data can\'t?', back: 'Access to current information from the internet, beyond the model\'s training cutoff.' },
  { id: 'fc-tool-file-search', topicId: 'agents-builtin-tools', front: 'What does the file_search tool actually search over?', back: 'Files you upload to a dedicated vector search index — it grounds responses in specific documents you provided, not the general web.' },
  { id: 'fc-tool-function', topicId: 'agents-builtin-tools', front: 'What does the function tool let an agent do?', back: 'Call custom functions in your own application code — the escape hatch for anything the built-in tools don\'t cover.' },
  { id: 'fc-mcp-discovery', topicId: 'agents-mcp', front: 'What problem does MCP tool discovery solve?', back: 'It lets an agent discover and use tools exposed by an MCP server at runtime, without you hand-wiring each tool integration into the agent\'s code.' },
  { id: 'fc-a2a-protocol', topicId: 'agents-a2a', front: 'What is the A2A protocol for, and how is it different from orchestration patterns?', back: 'A2A (Agent-to-Agent) lets independently-built agents — possibly on different frameworks or owned by different teams — communicate. Orchestration patterns (concurrent/sequential/etc.) coordinate agents *you* built together in one framework.' },
  { id: 'fc-agent-publish', topicId: 'agents-publishing', front: 'Name two places a Foundry agent can be published to reach users.', back: 'Microsoft Teams and Microsoft 365 (e.g. via Microsoft 365 Copilot integration) — beyond just calling it via API from your own app.' },
  { id: 'fc-framework-basechatclient', topicId: 'agents-framework', front: 'What does BaseChatClient actually abstract over, and why does that matter for an agent you’ve already built?', back: 'It’s the common interface every provider’s chat client implements (AzureOpenAIChatClient, an OpenAI client, an Anthropic client, etc.). Every Agent Framework agent derives from the same Agent base class regardless of provider, so switching providers means instantiating a different chat client and creating your agents from it — not rewriting the agent’s logic, tools, or orchestration.' },
  { id: 'fc-framework-agentsession-roles', topicId: 'agents-framework', front: 'AgentSession tracks conversation history with a structured message system. What are its four roles, and which one carries a tool’s result back to the model?', back: 'USER, ASSISTANT, SYSTEM, and TOOL. The TOOL role is what carries a tool’s output back into the conversation as its own distinct message — the explicit role structure (not just a flat text log) is what keeps multi-turn context straight across turns.' },
  { id: 'fc-orch-mechanism-handoff-vs-groupchat', topicId: 'agents-orchestration-patterns', front: 'Handoff and group chat both move control between agents dynamically. Mechanically, what does the *next* agent actually receive in each pattern?', back: 'In handoff, the next agent receives only a typed, structured routing/classification object (built from a Pydantic response_format and routed via Case/Default switch-case edges) — not the previous agent’s reasoning. In group chat, every agent reads and contributes to one shared conversation, so each participant sees every prior agent’s full turn.' },

  { id: 'fc-cu-def', topicId: 'content-understanding-overview', front: 'What is Azure Content Understanding, in one sentence?', back: 'A generative AI service that extracts insights and data from documents, images, audio, and video — one consistent API across all four content types.' },
  { id: 'fc-cu-modalities', topicId: 'content-understanding-overview', front: 'List the four content modalities Content Understanding analyzes.', back: 'Documents/forms, images, audio, and video.' },
  { id: 'fc-di-def', topicId: 'document-intelligence-overview', front: 'What is Azure Document Intelligence, in one sentence?', back: 'A cloud AI service that uses OCR and deep learning to extract text, key-value pairs, selection marks, and tables from *documents only*, returning structured JSON with bounding boxes.' },
  { id: 'fc-di-model-categories', topicId: 'document-intelligence-models', front: 'Name the three categories of Document Intelligence models.', back: 'Document analysis models (read/layout), prebuilt models (invoices, receipts, IDs — no training needed), and custom models (trained on your own labeled data).' },
  { id: 'fc-di-custom-types', topicId: 'document-intelligence-models', front: 'Custom template vs. custom neural models — what\'s the trade-off?', back: 'Template models are fast/cheap but need a fixed layout. Neural models cost more but handle varying layouts with higher accuracy.' },
  { id: 'fc-cu-analyzer', topicId: 'content-understanding-analyzer', front: 'What is a Content Understanding "analyzer"?', back: 'A configured schema of fields you want extracted from content — you define it, then run content through it via the API, Studio, or Foundry portal.' },
  { id: 'fc-knowledge-mining-flow', topicId: 'knowledge-mining', front: 'In a knowledge mining pipeline, what do an indexer and AI skills each do?', back: 'An indexer pulls data from a source into Azure AI Search. AI skills enrich that data during indexing (OCR, entity/key-phrase extraction, etc.) so the resulting index holds inferred insights, not just raw text.' },

  { id: 'fc-lang-overview', topicId: 'language-overview', front: 'What three tasks does Azure Language in Foundry Tools headline (as opposed to its deprecated capabilities)?', back: 'Language detection, named entity recognition, and PII extraction. (Sentiment analysis, summarization, and key-phrase extraction are marked deprecated — kept only for existing apps.)' },
  { id: 'fc-lang-ner', topicId: 'language-detect-entities', front: 'What does named entity recognition detect?', back: 'References to entities in text: people, locations, time periods, organizations, and more.' },
  { id: 'fc-lang-pii', topicId: 'language-pii', front: 'What does PII extraction actually let you do, beyond just detecting personal data?', back: 'Identify *and redact* personal details in text — not just flag that PII is present.' },
  { id: 'fc-lang-translate', topicId: 'language-translation', front: 'Text translation is part of which Azure AI Foundry Tool?', back: 'Azure Translator — its own, separate Foundry Tool, not a feature of Azure Language. Azure Language (detection/NER/PII), Azure Translator (text translation/transliteration), and Azure Speech (audio) are three sibling Foundry Tools, not one nested inside another.' },
  { id: 'fc-lang-mcp', topicId: 'language-mcp', front: 'What does the Azure Language MCP server let an agent do that calling the Language SDK directly doesn\'t?', back: 'Discover and call Language capabilities (detect language, extract entities, etc.) as agent tools at runtime, via the MCP protocol, instead of you hard-coding SDK calls into the agent.' },

  { id: 'fc-speech-config', topicId: 'speech-overview', front: 'What object do almost all Azure Speech SDK calls start from?', back: 'A SpeechConfig object, which encapsulates the connection details (endpoint/key) for the Speech resource.' },
  { id: 'fc-stt', topicId: 'speech-to-text', front: 'Speech to Text: input and output?', back: 'Audio in, text out — transcription.' },
  { id: 'fc-tts', topicId: 'text-to-speech', front: 'Text to Speech: input and output?', back: 'Text in, synthesized audio out.' },
  { id: 'fc-ssml', topicId: 'text-to-speech', front: 'What does SSML let you control that plain text-to-speech can\'t?', back: 'Speaking style (e.g. "cheerful"), phoneme pronunciation, prosody (pitch, timbre, rate), pauses/silence, say-as rules (dates, times, phone numbers), and inserted recorded audio — via markup around the text being synthesized. (Voice selection is a separate SpeechConfig/Synthesizer property, e.g. speech_synthesis_voice_name — not something this corpus\'s SSML list controls.)' },
  { id: 'fc-speech-translate', topicId: 'speech-translation', front: 'How is speech translation different from text translation?', back: 'Speech translation works on spoken audio, often in real time, through Azure Speech (TranslationRecognizer). Translating written text is a separate capability, reached through a different Foundry Tool (Translator) — different medium, different tool, not two modes of the same service.' },
  { id: 'fc-voice-live', topicId: 'voice-live', front: 'What kind of problem is the Voice Live API built for, that batch STT/TTS isn\'t?', back: 'Real-time, low-latency, two-way spoken conversation — not "record then transcribe" or "generate then play back," but live voice interaction.' },
  { id: 'fc-speech-mcp', topicId: 'speech-mcp', front: 'What is the Azure Speech MCP server the speech-side equivalent of?', back: 'The Azure Language MCP server — it exposes Speech capabilities as discoverable agent tools rather than requiring direct SDK integration.' },

  { id: 'fc-search-def', topicId: 'ai-search-overview', front: 'What is Azure AI Search, in one sentence?', back: 'Cloud infrastructure for indexing and querying data from structured, semi-structured, and unstructured sources, at scale — the engine underneath both knowledge mining and RAG grounding.' },
  { id: 'fc-rag-steps', topicId: 'rag-fundamentals', front: 'Name RAG\'s three steps, in order.', back: 'Retrieve (search knowledge bases for relevant content) → Augment (combine it with the user\'s question) → Generate (the agent answers using both retrieved content and training data).' },
  { id: 'fc-rag-why', topicId: 'rag-fundamentals', front: 'What three things does RAG give an agent that its training data alone can\'t?', back: 'Real-time updates without retraining, source transparency (citations), and factual grounding that reduces fabrication.' },
  { id: 'fc-foundry-iq-def', topicId: 'foundry-iq', front: 'What problem does Foundry IQ solve that "just build RAG on Azure AI Search yourself" doesn\'t?', back: 'It\'s a managed, *shared* knowledge layer: instead of building/maintaining a separate RAG pipeline per agent, you create knowledge bases once (by business domain, not storage location) and connect any number of agents to them.' },
  { id: 'fc-foundry-iq-kb', topicId: 'foundry-iq', front: 'How does Foundry IQ organize knowledge bases — by storage location or by something else?', back: 'By business domain (e.g. "Product Documentation," "HR Policies"), pulling together data from multiple underlying stores (SharePoint, Blob, OneLake) into one thing an agent searches.', },
  { id: 'fc-foundry-iq-auto', topicId: 'foundry-iq-data-sources', front: 'When you add a data source to Foundry IQ, what four things happen automatically?', back: 'Discovery (scan the source), processing (chunk + embed documents), indexing (make it searchable), and monitoring (reindex automatically when source content changes).' },

  { id: 'fc-catalog-size', topicId: 'model-catalog', front: 'What are the two broad categories of models in the Foundry Models catalog?', back: 'Models sold directly by Azure (billed through your Azure subscription, e.g. Azure OpenAI) and models from partners/community (their own licensing/pricing).' },
  { id: 'fc-llm-vs-slm', topicId: 'model-catalog', front: 'LLM vs. SLM — what\'s the trade-off?', back: 'LLMs (e.g. GPT-5-class) handle deep reasoning and complex generation but need more compute. SLMs (e.g. Phi-4-class) are cheaper/faster, good for common NLP tasks, and can run on edge devices — at the cost of top-end reasoning capability.' },
  { id: 'fc-embedding-models', topicId: 'model-catalog', front: 'What do embedding models do, and what do they enable?', back: 'Convert text into numerical vector representations, enabling semantic search, recommendations, and RAG (finding relevant info by meaning, not exact keywords).' },
  { id: 'fc-endpoint-choice', topicId: 'model-deployment', front: 'What two things do you choose when deploying a model to an endpoint?', back: 'Which endpoint type/SDK to call it through, and the deployment configuration for that model — turning a catalog entry into something your app can actually call.' },
  { id: 'fc-eval-when', topicId: 'model-evaluation', front: 'Why isn\'t evaluating a model once, right after you deploy it, enough?', back: 'Every evaluation approach in the lesson — playground testing, structured human review, automated metrics — runs against an already-deployed model or agent, not a pre-deployment candidate. But that doesn\'t make it a one-time check: you evaluate right after deployment to catch problems before real traffic depends on the model, and you keep re-evaluating afterward (as you change prompts, add features, or retrain) to catch drift or regressions once it\'s live.' },
  { id: 'fc-finetune-vs-rag', topicId: 'model-fine-tuning', front: 'Fine-tuning changes model *behavior*; what does RAG change instead?', back: 'RAG changes what *knowledge* is available at inference time (retrieved context), without altering model weights. Fine-tuning bakes a pattern of behavior/style/task performance into the weights themselves.' },
  { id: 'fc-image-gen', topicId: 'image-video-generation', front: 'What\'s the exam-relevant distinction between image-generation and image-analysis models?', back: 'Image-generation models create images from text (e.g. GPT-image-1). Image-analysis/vision models do the reverse — accept images as input and produce text output about them (e.g. GPT-4.1 multimodal).' },
]

